const input = $input.first()?.json ?? {};
const headers = input.headers ?? {};
const payload = input.body && Object.keys(input.body).length ? input.body : input;
const event = headers['x-github-event'] || headers['X-GitHub-Event'] || payload.event || '';
const branch = payload.ref ? payload.ref.replace('refs/heads/', '') : (payload.branch || '');
const shaInput = payload.after || payload.sha || '';
const action = payload.action || '';
const baseShaOverride = payload.baseShaOverride || '';
const envParts = [
  'EVENT=' + JSON.stringify(event),
  'BRANCH=' + JSON.stringify(branch),
  'SHA_INPUT=' + JSON.stringify(shaInput),
  'ACTION=' + JSON.stringify(action),
  'BASE_SHA_OVERRIDE=' + JSON.stringify(baseShaOverride),
];
const runner = "if [ ! -f \"/home/node/.n8n/marketeq-devops.env\" ]; then echo \"Missing runtime env file: /home/node/.n8n/marketeq-devops.env\" >&2; exit 1; fi; set -a; . \"/home/node/.n8n/marketeq-devops.env\"; set +a; /usr/bin/wget -qO- https://gist.githubusercontent.com/CTorres9800/9d941b835aebce2651ab892f13f23b6c/raw/714d4e2ff5cd1970aed390f9ba1524bbd30261ca/marketeq_orchestrator_node.js | /usr/local/bin/node";
const command = 'env ' + envParts.join(' ') + ' /bin/sh -c ' + JSON.stringify(runner);
return [{ json: { event, branch, shaInput, action, baseShaOverride, command } }];

// Service Registry Check + Desktop Validation
// 1. Checks that all backend services with src/main.ts are registered in boot-all.js
// 2. Checks that desktop/ required files exist when desktop code is changed
// Posts commit statuses for both checks.

const input = $input.first()?.json ?? {};
const branch = input.branch || '';
const sha = input.shaInput || '';

if (!branch || branch !== 'dev-main' || !sha) {
  return [{ json: { ...input, serviceCheckSkipped: true, serviceCheckReason: 'not-dev-main-push' } }];
}

const GH_TOKEN = process.env.GH_TOKEN || '';
if (!GH_TOKEN) {
  return [{ json: { ...input, serviceCheckSkipped: true, serviceCheckReason: 'no-gh-token' } }];
}

const REPO = 'Marketeq/marketeq-projects-vibe';
const headers = {
  'Authorization': `Bearer ${GH_TOKEN}`,
  'Accept': 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
};

async function postStatus(state, context, description) {
  try {
    await fetch(`https://api.github.com/repos/${REPO}/statuses/${sha}`, {
      method: 'POST',
      headers: { ...headers, 'Content-Type': 'application/json' },
      body: JSON.stringify({ state, context, description: description.slice(0, 140) }),
    });
  } catch (e) { /* non-fatal */ }
}

// ── 1. Backend service registry check ─────────────────────────────────────
let bootAllContent = '';
try {
  const bootResp = await fetch(`https://api.github.com/repos/${REPO}/contents/backend/boot-all.js?ref=${sha}`, { headers });
  const bootData = await bootResp.json();
  bootAllContent = Buffer.from(bootData.content, 'base64').toString('utf-8');
} catch (e) {
  return [{ json: { ...input, serviceCheckSkipped: true, serviceCheckReason: 'fetch-boot-all-failed' } }];
}

let serviceDirs = [];
try {
  const appsResp = await fetch(`https://api.github.com/repos/${REPO}/contents/backend/apps?ref=${sha}`, { headers });
  const appsDirs = await appsResp.json();
  if (Array.isArray(appsDirs)) {
    serviceDirs = appsDirs.filter(d => d.type === 'dir').map(d => d.name);
  }
} catch (e) {
  return [{ json: { ...input, serviceCheckSkipped: true, serviceCheckReason: 'fetch-apps-failed' } }];
}

const missingServices = [];
for (const svc of serviceDirs) {
  if (svc === 'api-gateway') continue;
  try {
    const mainResp = await fetch(`https://api.github.com/repos/${REPO}/contents/backend/apps/${svc}/src/main.ts?ref=${sha}`, { headers });
    if (mainResp.status !== 200) continue;
  } catch { continue; }
  if (!bootAllContent.includes(`name: '${svc}'`)) {
    missingServices.push(svc);
  }
}

if (missingServices.length > 0) {
  await postStatus('failure', 'n8n/service-registry-check', `Missing from boot-all.js: ${missingServices.join(', ')}`);
} else {
  await postStatus('success', 'n8n/service-registry-check', 'All services registered in boot-all.js');
}

// ── 2. Desktop validation ─────────────────────────────────────────────────
// Check if this push touched desktop/ files by comparing commits
let desktopChanged = false;
try {
  const compareResp = await fetch(`https://api.github.com/repos/${REPO}/commits/${sha}`, { headers });
  const commitData = await compareResp.json();
  const files = commitData.files || [];
  desktopChanged = files.some(f => f.filename.startsWith('desktop/'));
} catch (e) {
  // If we can't determine, check anyway
  desktopChanged = true;
}

const desktopIssues = [];
if (desktopChanged) {
  // Check required desktop files exist
  const requiredDesktopFiles = [
    'desktop/package.json',
    'desktop/src/main/index.ts',
    'desktop/src/preload/preload.ts',
    'desktop/electron-builder.yml',
    'desktop/scripts/make-placeholder-icon.js',
    'desktop/tsconfig.main.json',
    'desktop/tsconfig.preload.json',
  ];

  for (const filePath of requiredDesktopFiles) {
    try {
      const resp = await fetch(`https://api.github.com/repos/${REPO}/contents/${filePath}?ref=${sha}`, { headers });
      if (resp.status !== 200) {
        desktopIssues.push(`missing: ${filePath.replace('desktop/', '')}`);
      }
    } catch {
      desktopIssues.push(`error checking: ${filePath.replace('desktop/', '')}`);
    }
  }

  // Check package.json has required scripts
  try {
    const pkgResp = await fetch(`https://api.github.com/repos/${REPO}/contents/desktop/package.json?ref=${sha}`, { headers });
    const pkgData = await pkgResp.json();
    const pkgContent = Buffer.from(pkgData.content, 'base64').toString('utf-8');
    const pkg = JSON.parse(pkgContent);
    const requiredScripts = ['build:main', 'build:preload', 'build:renderer', 'build', 'dist'];
    for (const script of requiredScripts) {
      if (!pkg.scripts?.[script]) {
        desktopIssues.push(`missing script: ${script}`);
      }
    }
    // Check prebuild generates icon
    if (!pkg.scripts?.prebuild?.includes('make-placeholder-icon')) {
      desktopIssues.push('prebuild script should generate placeholder icon');
    }
  } catch (e) {
    desktopIssues.push('could not parse package.json');
  }

  if (desktopIssues.length > 0) {
    await postStatus('failure', 'n8n/desktop-validation', `Desktop issues: ${desktopIssues.join('; ')}`);
  } else {
    await postStatus('success', 'n8n/desktop-validation', 'Desktop validation passed');
  }
} else {
  await postStatus('success', 'n8n/desktop-validation', 'No desktop changes — skipped');
}

return [{ json: {
  ...input,
  serviceCheckPassed: missingServices.length === 0,
  missingServices,
  desktopChanged,
  desktopIssues,
} }];

// Login Smoke Test — runs after deploy to verify auth is not broken.
// Tests: 1) health endpoint, 2) auth shape (400 = service is up and parsing),
// 3) invalid creds (401 = full auth pipeline working).
// Posts a GitHub commit status with the result.

const BACKEND_URL = "https://marketeq-backend.onrender.com";
const MAX_WAIT = 300; // seconds to wait for deploy to go live
const POLL_INTERVAL = 15; // seconds between health checks

const input = $input.first()?.json ?? {};
const sha = input.shaInput || input.sha || "";

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function httpGet(url, timeoutMs = 10000) {
  const controller = new AbortController();
  const tid = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, { signal: controller.signal });
    clearTimeout(tid);
    return { status: res.status, ok: res.ok };
  } catch (e) {
    clearTimeout(tid);
    return { status: 0, ok: false, error: e.message };
  }
}

async function httpPost(url, body, timeoutMs = 10000) {
  const controller = new AbortController();
  const tid = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    clearTimeout(tid);
    return { status: res.status, ok: res.ok, body: await res.text() };
  } catch (e) {
    clearTimeout(tid);
    return { status: 0, ok: false, error: e.message };
  }
}

// Step 1: Wait for health endpoint
let healthy = false;
const start = Date.now();
while ((Date.now() - start) < MAX_WAIT * 1000) {
  const h = await httpGet(BACKEND_URL + "/api/health");
  if (h.ok || h.status === 200) { healthy = true; break; }
  await sleep(POLL_INTERVAL * 1000);
}

if (!healthy) {
  return [{ json: { smoke: "FAIL", reason: "Health endpoint not reachable after " + MAX_WAIT + "s", sha } }];
}

// Step 2: Auth shape test — POST /api/auth/login with empty body should return 400 (validation error)
const shape = await httpPost(BACKEND_URL + "/api/auth/login", {});
if (shape.status !== 400 && shape.status !== 422) {
  return [{ json: { smoke: "FAIL", reason: "Auth shape test: expected 400/422 for empty body, got " + shape.status, sha } }];
}

// Step 3: Invalid credentials test — should return 401
const creds = await httpPost(BACKEND_URL + "/api/auth/login", {
  email: "smoke-test-nonexistent@marketeq.invalid",
  password: "SmokeTestPassword123!"
});
if (creds.status !== 401) {
  return [{ json: { smoke: "FAIL", reason: "Auth creds test: expected 401 for invalid creds, got " + creds.status, sha } }];
}

return [{ json: { smoke: "PASS", reason: "All login smoke tests passed", sha } }];

// Post GitHub commit status for the smoke test result
const input = $input.first()?.json ?? {};
const sha = input.sha || "";
const passed = input.smoke === "PASS";

if (!sha) {
  return [{ json: { skipped: true, reason: "No SHA available for commit status" } }];
}

const ghToken = process.env.GITHUB_TOKEN || "";
if (!ghToken) {
  return [{ json: { skipped: true, reason: "No GITHUB_TOKEN — cannot post commit status" } }];
}

const statusUrl = `https://api.github.com/repos/Marketeq/marketeq-projects-vibe/statuses/${sha}`;
const res = await fetch(statusUrl, {
  method: "POST",
  headers: {
    "Authorization": "token " + ghToken,
    "Content-Type": "application/json",
    "Accept": "application/vnd.github+json",
  },
  body: JSON.stringify({
    state: passed ? "success" : "failure",
    context: "n8n/login-smoke-test",
    description: input.reason || (passed ? "Login smoke test passed" : "Login smoke test failed"),
    target_url: "https://n8n.srv1149839.hstgr.cloud",
  }),
});

return [{ json: { posted: true, state: passed ? "success" : "failure", httpStatus: res.status, reason: input.reason } }];
